#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/zbus/zbus.h>
#include <stdlib.h>

#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(zbus, CONFIG_ZBUS_LOG_LEVEL);

ZBUS_CHAN_DEFINE(dyn_chan,		/* Name */
		 bool,			/* Message type */
		 NULL,			/* Validator */
		 NULL,			/* User data */
		 ZBUS_OBSERVERS_EMPTY,	/* observers */
		 ZBUS_MSG_INIT(false)	/* Initial value */
);

static volatile bool s1_cb_called;

static void s1_cb(const struct zbus_channel *chan)
{
	s1_cb_called = true;
	LOG_DBG("Callback called");
}

static void *dynamic_suite_setup(void)
{
	/*
	 * The dynamic suite alters the zbus oberver lists at runtime.
	 * To ensure that other test suites are not affected by this, we
	 * must wait for the zbus thread to be idle before running the
	 * suite, and before finishing it.
	 */
	zbus_chan_pub(&dyn_chan, &((bool){false}), K_MSEC(500));
	k_msleep(100);

	return NULL;
}

static void dynamic_suite_teardown(void *data)
{
	ARG_UNUSED(data);

	zbus_chan_pub(&dyn_chan, &((bool){false}), K_MSEC(500));
	k_msleep(100);
}

ZTEST_SUITE(dynamic, NULL, dynamic_suite_setup, NULL, NULL, dynamic_suite_teardown);

ZTEST(dynamic, test_malloc)
{
	int err;
	struct zbus_observer *obs = malloc(sizeof(struct zbus_observer));

	zassert_not_null(obs, "malloc failed");

	obs->callback = s1_cb;
	/* This is important, malloc does not guarantee that the memory is zeroed. The queue
	 * must be NULL for regular observers. Not setting it will cause a page fault.
	 */
	obs->queue = NULL;
	obs->enabled = true;

	s1_cb_called = false;

	err = zbus_obs_add(&dyn_chan, obs, K_MSEC(500));
	zassert_equal(err, 0, "zbus_obs_add failed with err %d", err);

	err = zbus_chan_pub(&dyn_chan, &((bool){true}), K_MSEC(500));
	zassert_equal(err, 0, "zbus_chan_pub failed with err %d", err);

	zassert_true(s1_cb_called, "s1_cb not called");

	err = zbus_obs_remove(&dyn_chan, obs, K_MSEC(500));
	zassert_equal(err, 0, "zbus_obs_remove failed with err %d", err);

	free(obs);
}

ZTEST(dynamic, test_calloc)
{
	int err;
	struct zbus_observer *obs = calloc(1, sizeof(struct zbus_observer));

	zassert_not_null(obs, "calloc failed");

	obs->callback = s1_cb;
	obs->enabled = true;

	s1_cb_called = false;

	err = zbus_obs_add(&dyn_chan, obs, K_MSEC(500));
	zassert_equal(err, 0, "zbus_obs_add failed with err %d", err);

	err = zbus_chan_pub(&dyn_chan, &((bool){true}), K_MSEC(500));
	zassert_equal(err, 0, "zbus_chan_pub failed with err %d", err);

	zassert_true(s1_cb_called, "s1_cb not called");

	err = zbus_obs_remove(&dyn_chan, obs, K_MSEC(500));
	zassert_equal(err, 0, "zbus_obs_remove failed with err %d", err);

	free(obs);
}
